92	```rust
93	use std::task::{Context, Poll, Waker};
94	use std::pin::Pin;
95	use std::future::Future;
96	use std::sync::{Arc, Mutex};
97	use std::thread;
98	use std::time::Duration;
99	
100	/// A future that completes after a delay (toy implementation)
101	struct Delay {
102	    completed: Arc<Mutex<bool>>,
103	    waker_stored: Arc<Mutex<Option<Waker>>>,
104	    duration: Duration,
105	    started: bool,
106	}
107	
108	impl Delay {
109	    fn new(duration: Duration) -> Self {
110	        Delay {
111	            completed: Arc::new(Mutex::new(false)),
112	            waker_stored: Arc::new(Mutex::new(None)),
113	            duration,
114	            started: false,
115	        }
116	    }
117	}
118	
119	impl Future for Delay {
120	    type Output = ();
121	
122	    fn poll(mut self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<()> {
123	        // Check if already completed before storing waker
124	        if *self.completed.lock().unwrap() {
125	            return Poll::Ready(());
126	        }
127	
128	        // Store the waker - executor may pass a new one on each poll
129	        *self.waker_stored.lock().unwrap() = Some(cx.waker().clone());
130	
131	        // Start the background timer on first poll
132	        if !self.started {
133	            self.started = true;
134	            let completed = Arc::clone(&self.completed);
135	            let waker = Arc::clone(&self.waker_stored);
136	            let duration = self.duration;
137	
138	            thread::spawn(move || {
139	                thread::sleep(duration);
140	                *completed.lock().unwrap() = true;
141	
142	                // CRITICAL: wake the executor so it polls us again
143	                if let Some(w) = waker.lock().unwrap().take() {
144	                    w.wake(); // "Hey executor, I'm ready — poll me again!"
145	                }
146	            });
147	        }
148	
149	        // Double-check completion after storing waker (handles race condition)
150	        if *self.completed.lock().unwrap() {
151	            return Poll::Ready(());
152	        }
153	
154	        Poll::Pending // Not done yet
155	    }
156	}
157	```
