191	    type Output = &'static str;
192	
193	    fn poll(mut self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
194	        if self.count == 0 {
195	            println!("Liftoff!");
196	            Poll::Ready("Liftoff!")
197	        } else {
198	            println!("{}...", self.count);
199	            self.count -= 1;
