63	### Exercise 2: Concurrent URL Fetcher with Rate Limiting
64	
65	Fetch a list of URLs concurrently, with at most 5 concurrent requests.
66	
67	<details>
68	<summary>🔑 Solution</summary>
69	
70	```rust
71	use futures::stream::{self, StreamExt};
72	use tokio::time::{sleep, Duration};
73	
74	async fn fetch_urls(urls: Vec<String>) -> Vec<Result<String, String>> {
75	    // buffer_unordered(5) ensures at most 5 futures are polled
76	    // concurrently — no separate Semaphore needed here.
77	    let results: Vec<_> = stream::iter(urls)
78	        .map(|url| {
79	            async move {
80	                println!("Fetching: {url}");
81	
82	                match reqwest::get(&url).await {
83	                    Ok(resp) => match resp.text().await {
84	                        Ok(body) => Ok(body),
85	                        Err(e) => Err(format!("{url}: {e}")),
86	                    },
87	                    Err(e) => Err(format!("{url}: {e}")),
88	                }
89	            }
90	        })
91	        .buffer_unordered(5) // ← This alone limits concurrency to 5
92	        .collect()
93	        .await;
94	
95	    results
96	}
97	
98	// NOTE: Use Semaphore when you need to limit concurrency across
99	// independently spawned tasks (tokio::spawn). Use buffer_unordered
100	// when processing a stream. Don't combine both for the same limit.
101	```
