107	### Exercise 3: Graceful Shutdown with Worker Pool
108	
109	Build a task processor with:
110	- A channel-based work queue
111	- N worker tasks consuming from the queue
112	- Graceful shutdown on Ctrl+C: stop accepting, finish in-flight work
113	
114	<details>
115	<summary>🔑 Solution</summary>
116	
117	```rust
118	use tokio::sync::{mpsc, watch};
119	use tokio::time::{sleep, Duration};
120	
121	struct WorkItem {
122	    id: u64,
123	    payload: String,
124	}
125	
126	#[tokio::main]
127	async fn main() {
128	    let (work_tx, work_rx) = mpsc::channel::<WorkItem>(100);
129	    let (shutdown_tx, shutdown_rx) = watch::channel(false);
130	
131	    // Spawn 4 workers
132	    let mut worker_handles = Vec::new();
133	    let work_rx = std::sync::Arc::new(tokio::sync::Mutex::new(work_rx));
134	
135	    for id in 0..4 {
136	        let rx = work_rx.clone();
137	        let mut shutdown = shutdown_rx.clone();
138	        let handle = tokio::spawn(async move {
139	            loop {
140	                let item = {
141	                    let mut rx = rx.lock().await;
142	                    tokio::select! {
143	                        item = rx.recv() => item,
144	                        _ = shutdown.changed() => {
145	                            if *shutdown.borrow() { None } else { continue }
146	                        }
147	                    }
148	                };
149	
150	                match item {
151	                    Some(work) => {
152	                        println!("Worker {id}: processing item {}", work.id);
153	                        sleep(Duration::from_millis(200)).await; // Simulate work
154	                        println!("Worker {id}: done with item {}", work.id);
155	                    }
156	                    None => {
157	                        println!("Worker {id}: channel closed, exiting");
158	                        break;
159	                    }
160	                }
161	            }
162	        });
163	        worker_handles.push(handle);
164	    }
165	
166	    // Producer: submit some work
167	    let producer = tokio::spawn(async move {
168	        for i in 0..20 {
169	            let _ = work_tx.send(WorkItem {
170	                id: i,
171	                payload: format!("task-{i}"),
172	            }).await;
173	            sleep(Duration::from_millis(50)).await;
174	        }
175	    });
176	
177	    // Wait for Ctrl+C
178	    tokio::signal::ctrl_c().await.unwrap();
179	    println!("\nShutdown signal received!");
180	    shutdown_tx.send(true).unwrap();
181	    producer.abort(); // Cancel the producer task
182	
183	    // Wait for workers to finish
184	    for handle in worker_handles {
185	        let _ = handle.await;
186	    }
187	    println!("All workers shut down. Goodbye!");
188	}
189	```
190	
191	</details>
